#!/usr/bin/env node
// UserPromptSubmit hook: when the prompt contains the trigger word, inject the model
// routing policy into that turn.
//
// Why a hook and not a memory or a CLAUDE.md line:
//   - memory       fails exactly when you're in a hurry, which is when it matters
//   - CLAUDE.md    always on, always costs context, and gets read without being applied
//   - hook + word  the harness runs it, the model can't forget, and it costs nothing
//                  on the turns you don't ask for it
//
// The policy is DATA, not code. Edit routing.json — do not edit this file.
// Precedence: $CROSSMODEL_ROUTING > ./routing.json (plugin root) > built-in default.

import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { readMode, clearMode, describeUntil, USER_ROUTING_PATH } from '../lib/mode.mjs';

// fileURLToPath, not `new URL(...).pathname` — the latter is percent-encoded, so a plugin
// path containing a space silently resolves to a directory that does not exist.
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// The trigger requires a leading '#'. Do not drop it: bare words like "route" collide
// with everyday vocabulary ("fix the /api route") and the hook would fire constantly.
const DEFAULT_TRIGGER = '#route';

const BUILT_IN = {
  trigger: DEFAULT_TRIGGER,
  // ⚠️ These are UNMEASURED defaults — a starting shape, not a recommendation.
  // Run `node bench/battery.mjs` against your own tasks and replace them.
  measured: false,
  rules: [
    ['Self-contained function from a spec, with tests', 'cheap external model via `delegate`'],
    ['Convert / extract / normalise structured data', 'cheap external model via `delegate`'],
    ['Classify or triage a batch into a closed list', 'cheap external model via `delegate`'],
    ['Sweep the repo: where is X, which files touch Y', 'cheap CLI-backed model via `delegate` + --cwd'],
    ['Investigate / diagnose across the repo', 'cheap CLI-backed model + --cwd, strong model confirms'],
    ['Filter candidates in a broad sweep', 'cheap model filters, strong model confirms'],
    ['Implement inside the existing codebase (writing files)', 'mid-tier Claude subagent — external models are read-only here'],
    ['Read a lot, conclude a little', 'ALWAYS a subagent — the win is the context that never enters yours'],
    ['Final review, subtle defect, security', 'strongest model, main loop'],
    ['Trade-off that is expensive to reverse', 'strongest model, main loop'],
    ['Independent second opinion', 'a model from a different family via `delegate`'],
  ],
  unused: [],
};

function loadPolicy() {
  const candidates = [
    process.env.CROSSMODEL_ROUTING,
    // $HOME first: a plugin update installs into a new versioned directory, so a
    // routing.json written into the plugin root would be silently discarded and the
    // user would drop back to unmeasured defaults without being told.
    USER_ROUTING_PATH,
    path.join(ROOT, 'routing.json'),
  ].filter(Boolean);
  for (const p of candidates) {
    if (!existsSync(p)) continue;
    try {
      const raw = JSON.parse(readFileSync(p, 'utf8'));
      // Syntax was already guarded; SHAPE was not, and that is the gap that mattered.
      // `{"rules": {}}` is valid JSON, reaches `policy.rules.map` in render(), throws, and
      // kills the hook on EVERY prompt — a file the user is invited to hand-edit taking
      // down the harness integration until they work out why.
      if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
        return { ...BUILT_IN, parseError: `${path.basename(p)}: expected a JSON object` };
      }
      if (raw.rules !== undefined && !(Array.isArray(raw.rules) && raw.rules.every((r) => Array.isArray(r) && r.length >= 2))) {
        return { ...BUILT_IN, parseError: `${path.basename(p)}: "rules" must be an array of [situation, route] pairs` };
      }
      if (raw.unused !== undefined && !Array.isArray(raw.unused)) {
        return { ...BUILT_IN, parseError: `${path.basename(p)}: "unused" must be an array` };
      }
      return { ...BUILT_IN, ...raw, source: p };
    } catch (e) {
      // A malformed policy must not silently fall back to defaults — that would be the
      // exact failure mode this plugin exists to prevent.
      return { ...BUILT_IN, parseError: `${path.basename(p)}: ${e.message}` };
    }
  }
  return BUILT_IN;
}

function render(policy) {
  const pad = Math.max(...policy.rules.map(([k]) => k.length));
  const lines = policy.rules.map(([k, v]) => `- ${k.padEnd(pad)} ..... ${v}`);
  const unused = policy.unused?.length
    ? `\nNOT IN USE: ${policy.unused.map(([m, why]) => `${m} (${why})`).join('; ')}`
    : '';
  const caveat = policy.measured
    ? `Routing below is backed by your own benchmark run.`
    : `⚠️ Routing below is an UNMEASURED default. Run \`node bench/battery.mjs\` against your\nown tasks and write the result into routing.json before treating it as authoritative.`;
  const parseWarning = policy.parseError
    ? `\n🔴 routing.json could not be parsed (${policy.parseError}) — showing built-in defaults instead. Fix the file.\n`
    : '';

  return `<crossmodel_routing trigger="${policy.trigger}">
ROUTING ACTIVE. Before you execute, pick the layer and SAY in one line which you picked.
${parseWarning}
${caveat}

${lines.join('\n')}${unused}

THE RULE THAT IS NOT NEGOTIABLE
Only delegate work that a deterministic verifier can check afterwards — a test, a
typecheck, a schema validation, a closed list, a project gate. A benchmark score
measures the pair model+verifier, not the model alone: remove the verifier and you have
no way to know when it was wrong. No verifier available? Move it up a tier.

HOW DELEGATION ACTUALLY WORKS
Every provider here is an AGENTIC CLI: give it --cwd and it greps and reads the tree
itself. You do not paste code into the prompt, and a repo-wide sweep costs their quota,
not yours. With --write it may also edit, confined to that directory.
What it cannot see is THIS conversation — so state the goal, the constraints and the
definition of done explicitly, every time.

SUBAGENTS WRITE AND PROVE — YOU REVIEW AND COMMIT
Delegated models may edit files (--write with an explicit --cwd, confined to it) and must
run the gate. What they never do is COMMIT. The checkpoint is not who touched the file,
it is what enters history: in the working tree a change is a diff you can throw away;
after a commit it is a fact other work builds on.
Review is yours because only you see the other slices in flight and the original intent —
a delegated model holds exactly the view you handed it. For anything sizeable, give it a
git worktree so two agents never share a tree.
The saving is untouched: sweeping, reasoning, drafting and testing ran on their quota.
Only review and commit come home.

OBLIGATIONS
1. Subagents do NOT inherit this conversation. Self-contained briefing: objective, file
   paths, definition of done, output format. A bad briefing turns a cheap model into
   expensive rework.
2. Independent agents run in PARALLEL, in a single message.
3. If you decide NOT to delegate, JUSTIFY it in one line. Doing everything yourself out
   of habit is the failure mode this rule exists to prevent.
</crossmodel_routing>`;
}

// Saver mode injects on EVERY turn, so it has to stay small — this is a standing bias,
// not a briefing. The full policy is still one `#route` away.
function renderSaver(mode, now) {
  const pref = mode.model ? mode.model : 'the cheapest model that clears the bar';
  return `<crossmodel_saver>
QUOTA SAVER ACTIVE — ${describeUntil(mode.until, now)}.
This session's quota is nearly spent. The external provider's is not. Spend theirs.

Default to delegating. If a delegatable step is NOT delegated, justify it in one line.

Delegate by default (prefer ${pref}):
- "where is X" / "which files touch Y" / "does this pattern exist" — sweep with --cwd,
  do not Read and Grep your way there yourself
- read a lot to conclude a little — sweep, and ask several questions in ONE sweep
- code from a spec a test can check — --write in an isolated dir, then review the diff
- bulk conversion, classification into a closed list, independent second opinion

Call the CLI STRAIGHT FROM BASH:
  crossmodel --model <alias> --cwd <dir> "<self-contained question>"
The \`delegate\` subagent is itself a Claude model and spends the quota you are saving.
Reach for it only when the output is large or the batch is long.

Still yours, and not negotiable: final review, decisions expensive to reverse, and the
commit. Never delegate what no verifier can check — no test, no typecheck, no closed
list means move it back up a tier.
</crossmodel_saver>`;
}

let buf = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (c) => { buf += c; });
process.stdin.on('end', () => {
  let prompt = '';
  try { prompt = JSON.parse(buf || '{}').prompt || ''; } catch { /* malformed payload: do nothing */ }

  const now = new Date();
  const mode = readMode(now);
  const policy = loadPolicy();
  const trigger = policy.trigger || DEFAULT_TRIGGER;
  // Escape the trigger so a user-supplied value can't inject regex syntax.
  const escaped = trigger.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const triggered = new RegExp(`(^|\\s)${escaped}\\b`, 'i').test(prompt);

  // Expiry is announced, not silent: the user turned this on to protect a budget and has
  // to know the protection ended.
  if (mode.expired) {
    clearMode();
    process.stdout.write(JSON.stringify({
      systemMessage: `crossmodel: saver mode expired (${new Date(mode.until).toLocaleString()}) — back to normal routing.`,
      ...(triggered && {
        hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: render(policy) },
      }),
    }));
    process.exit(0);
  }

  // A broken mode.json must not take #route down with it. The `expired` branch above
  // carefully preserves the injection when the trigger was used; this one dropped it, so a
  // one-character typo in an unrelated state file silently disabled a feature that has
  // nothing to do with saver mode.
  if (mode.error) {
    process.stdout.write(JSON.stringify({
      systemMessage: `🔴 crossmodel: ${mode.error} — saver mode is NOT active. Fix the file or run \`crossmodel mode off\`.`,
      ...(triggered && {
        hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: render(policy) },
      }),
    }));
    process.exit(0);
  }

  if (!triggered && !mode.active) process.exit(0);

  // #route asked for the full policy; saver mode alone gets the compact reminder.
  const context = triggered
    ? (mode.active ? `${renderSaver(mode, now)}\n\n${render(policy)}` : render(policy))
    : renderSaver(mode, now);

  const note = triggered
    ? `${trigger} — routing policy injected${policy.measured ? '' : ' (unmeasured defaults)'}`
    : null;

  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: context },
    ...(note && { systemMessage: note }),
  }));
  process.exit(0);
});
